insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"mesoestetic","slug":"follicle-repair-serum","title_zh_hk":"\u5f37\u5316\u6bdb\u56ca\u4fee\u5fa9\u7cbe\u83ef","title_zh_cn":"\u5f3a\u5316\u6bdb\u56ca\u4fee\u590d\u7cbe\u534e","title_en":"Follicle Repair Serum","description_zh_hk":"<p>\u982d\u9aee\u53ca\u6bdb\u56ca\u751f\u9577\u7684\u5065\u5eb7\u7a0b\u5ea6\u53d6\u6c7a\u65bc\u6bdb\u6bcd\u7d30\u80de\u542b\u91cf\uff0c\u6b64\u7522\u54c1\u4e4b\u6709\u6548\u6210\u5206\u80fd\u589e\u52a0\u6bdb\u6bcd\u7d30\u80de\u542b\u91cf\uff0c\u52a0\u5feb\u5206\u88c2\u901f\u5ea6\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u52a0\u5f37\u6bdb\u56ca\u5468\u908a\u7684\u8840\u6db2\u6d41\u91cf\uff0c\u5c07\u6240\u9700\u990a\u4efd\u66a2\u901a\u7121\u963b\u5730\u5085\u9001\u81f3\u6bdb\u56ca</p>\n<p>\u2013 \u6291\u52365a-\u9084\u539f\u9175\u7d20I\u53caII\uff0c\u6e1b\u5c11\u5c0d\u6bdb\u56ca\u6709\u76f4\u63a5\u5f71\u97ff\u7684DHT</p>\n<p>\u2013 \u6e1b\u5c11\u982d\u9aee\u6298\u65b7\u53ca\u5c0d\u6297\u812b\u9aee</p>\n<p>\u2013 \u52a0\u901f\u982d\u9aee\u751f\u9577\u901f\u5ea6</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u9f4a\u58a9\u679c\u9178</p>\n<p>\u2013 \u767d\u8336\u8403\u53d6\u7269</p>\n<p>\u2013 \u5f37\u5316\u6bdb\u56ca\u6fc3\u7e2e\u86cb\u767d</p>","description_zh_cn":"<p>\u5934\u53d1\u53ca\u6bdb\u56ca\u751f\u957f\u7684\u5065\u5eb7\u7a0b\u5ea6\u53d6\u51b3\u4e8e\u6bdb\u6bcd\u7ec6\u80de\u542b\u91cf\uff0c\u6b64\u4ea7\u54c1\u4e4b\u6709\u6548\u6210\u5206\u80fd\u589e\u52a0\u6bdb\u6bcd\u7ec6\u80de\u542b\u91cf\uff0c\u52a0\u5feb\u5206\u88c2\u901f\u5ea6\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u52a0\u5f3a\u6bdb\u56ca\u5468\u8fb9\u7684\u8840\u6db2\u6d41\u91cf\uff0c\u5c06\u6240\u9700\u517b\u4efd\u7545\u901a\u65e0\u963b\u5730\u5085\u9001\u81f3\u6bdb\u56ca</p>\n<p>\u2013 \u6291\u52365a-\u8fd8\u539f\u9175\u7d20I\u53caII\uff0c\u51cf\u5c11\u5bf9\u6bdb\u56ca\u6709\u76f4\u63a5\u5f71\u54cd\u7684DHT</p>\n<p>\u2013 \u51cf\u5c11\u5934\u53d1\u6298\u65ad\u53ca\u5bf9\u6297\u8131\u53d1</p>\n<p>\u2013 \u52a0\u901f\u5934\u53d1\u751f\u957f\u901f\u5ea6</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u9f50\u58a9\u679c\u9178</p>\n<p>\u2013 \u767d\u8336\u8403\u53d6\u7269</p>\n<p>\u2013 \u5f3a\u5316\u6bdb\u56ca\u6d53\u7f29\u86cb\u767d</p>","description_en":"<p>Supports hair and follicle health by increasing hair matrix cell content and division rate.</p>\n<p>Key benefits</p>\n<p>\u2013 Improves peri-follicular blood flow to deliver nutrients</p>\n<p>\u2013 Inhibits 5-alpha-reductase I and II to reduce DHT impact on follicles</p>\n<p>\u2013 Helps reduce breakage and hair loss</p>\n<p>\u2013 Helps accelerate hair growth</p>\n<p>Key ingredients</p>\n<p>\u2013 Oleanolic acid</p>\n<p>\u2013 White tea extract</p>\n<p>\u2013 Follicle-strengthening concentrated protein</p>","price_hkd":860,"stock":20,"image_paths":["/images/products/prod-7@2x.jpg"],"sort":223}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;